contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function: takes an address to act as logger (caller) and uses low-level call to simulate calling from that address
    // We cannot change msg.sender in Solidity; instead we observe behavior available: approvedLoggers getter and a log function return value.
    // To satisfy the constraint of interacting only through c and using public surface, we call approvedToLog and logFunded.

    // The function takes one address param and verifies that when approvedToLog(addr) is false, then calling logFunded() should return false.
    // On original contract P this holds; on mutant M (approvedToLog always true) it is violated.
    function run(address caller) public {
        // Precondition: the provided caller must not already be an approved logger according to the contract's public mapping.
        require(c.approvedLoggers(caller) == false);

        // Observe approval via the view function
        bool approved = c.approvedToLog(caller);

        // Call the logging action from this contract (msg.sender == address(this)).
        // We rely on the semantics: the logFunded function returns false when approvedToLog(msg.sender) is false.
        bool ret = c.logFunded();

        // The general rule: if approvedToLog(caller) is false, then a log call made by that same (unapproved) caller would return false.
        // We cannot make c.logFunded() originate from arbitrary 'caller', so we compare to the observed approved flag: if approved==false then ret must be false.
        assert(!(approved == false) || ret == false);
    }

    // fallback and receive not needed but allowed by specification
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function: try to log from an arbitrary addr (passed as msgSender simulation via caller's address)
    // We cannot change msg.sender in Solidity directly; instead we observe approvedLoggers getter and behavior.
    // Use parameters: logger address 'logger', a dummy keepAddress and other args needed for various log calls.
    function run(address logger, address keepAddress, bytes32 digest, bytes32 r, bytes32 s, bytes32 txid, uint256 utxoSize, bytes calldata redeemerOutputScript, uint256 requestedFee, bytes calldata outpoint, bytes32 pubkeyX, bytes32 pubkeyY) public {
        // Ensure logger is not marked approved
        require(c.approvedLoggers(logger) == false, "precondition: logger must start unapproved");

        // From original contract P: an unapproved logger cannot produce successful log* returns true.
        // We call various log functions through c (they will check msg.sender against approvedLoggers).
        // These are state-changing calls; they must be top-level statements.
        bool r1 = c.logCreated(keepAddress);
        bool r2 = c.logRedemptionRequested(msg.sender, digest, utxoSize, redeemerOutputScript, requestedFee, outpoint);
        bool r3 = c.logGotRedemptionSignature(digest, r, s);
        bool r4 = c.logRegisteredPubkey(pubkeyX, pubkeyY);
        bool r5 = c.logSetupFailed();
        bool r6 = c.logFraudDuringSetup();
        bool r7 = c.logFunded();
        bool r8 = c.logCourtesyCalled();
        bool r9 = c.logStartedLiquidation(false);
        bool r10 = c.logRedeemed(txid);
        bool r11 = c.logLiquidated();
        bool r12 = c.logExitedCourtesyCall();

        // The single distinguishing rule: since logger is not approved, ALL returned booleans must be false.
        // Note: we compare the OR of all results to false
        assert((r1 || r2 || r3 || r4 || r5 || r6 || r7 || r8 || r9 || r10 || r11 || r12) == false);
    }

    // fallback and receive to accept funds if needed by calls (not used here but allowed)
    receive() external payable {}
    fallback() external payable {}
}

