pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameter: an arbitrary address that the fuzzer picks.
    // We compare the contract's approvedToLog return against the public mapping getter approvedLoggers(address).
    // General rule: for any address a, c.approvedToLog(a) == c.approvedLoggers(a).
    // The mutant breaks this by making the contract owner always approved.
    function testFuzz_property(address potentialLogger) public {
        // keep domain wide; no assumptions needed

        // Read the public mapping getter directly
        bool mappingValue = c.approvedLoggers(potentialLogger);

        // Call the approvedToLog view; capture via try/catch in case of unexpected revert (shouldn't revert)
        bool ok;
        bool returned;
        try c.approvedToLog(potentialLogger) returns (bool r) {
            ok = true;
            returned = r;
        } catch {
            ok = false;
            returned = false;
        }

        // Assert the property: approvedToLog(address) must equal approvedLoggers[address]
        // (This will hold for the reference implementation for all inputs, but fail on the mutant when potentialLogger == owner)
        assertTrue(ok && (returned == mappingValue));
    }
}

